  choices = $EXPL$["In both scenarios the $150,000 gain is eliminated and $30,000 excess depreciation is reversed annually; downstream charges the parent fully while upstream allocates 20% to NCI","The upstream sale requires no consolidation adjustments because the parent is receiving an asset from a subsidiary it controls","Downstream sales never require elimination because the parent is the controlling entity, while upstream sales require full elimination","The depreciation adjustment differs between upstream and downstream because the asset''s useful life changes depending on the direction of transfer"]$EXPL$::jsonb,
